from itertools import combinations

def check(S, k):
    """Check if each element of S can be written as sum of k distinct others."""
    Sset = set(S)
    for x in S:
        others = [a for a in S if a != x]
        found = False
        for combo in combinations(others, k):
            if sum(combo) == x:
                found = True
                break
        if not found:
            return False
    return True

def search(k, n, rng=range(-12, 13)):
    """Search for a set of n distinct integers in rng that works for given k."""
    count = 0
    for S in combinations(rng, n):
        count += 1
        if check(S, k):
            return S, count
    return None, count

# Search for k=2
for n in range(3, 10):
    result, count = search(2, n)
    if result:
        print(f"k=2, n={n}: FOUND {result} (checked {count} sets)")
        break
    else:
        print(f"k=2, n={n}: impossible (checked {count} sets)")
